  };
  const ctx: any = {
    isIdle: () => false,
    hasUI: false,
    ui: {
      notify(text: string, level: string) { notifies.push({ text, level }); },
      setStatus(key: string, text: string | undefined) { status.set(key, text); },
      theme: { fg: (_color: string, text: string) => text },
    },
  };
