    fileExists: async (path) => files.has(path),
    readArtifact: async (phase, dir) => content.get(`${dir}/${taskMode.config.phaseArtifacts[phase]}`),
    readFile: async (path) => content.get(path),
    mkdirArtifactDir: async () => {},
    artifactPathFor: () => "/task-run",
