const HANDOFF_OK = "# Handoff\nWORKFLOW_HANDOFF_STATUS: ready";
const LOOP_COMPLETE_OK = "# Loop\nWORKFLOW_LOOP_STATUS: clean";
const REVIEW_OK = "# Review\nWORKFLOW_REVIEW_STATUS: clean";
